options.css:
.progressBar-container{
	background-color:#ebeff0;
}
.progressBar-bar{
	background-color:#008996;
	position: absolute;
}
.progressbar{
	height: 30px;
}
.progressBar-customControlContainer{
	width: 50%;
	position: relative;
}
.progressBar-text{
	color:grey;
	padding-top: 10px;
	padding-bottom: 5px;
}
.progressBar-count{
	text-align:left;
}
.progressBar-percentage{
	color: black;
	left: 50%;
	position: absolute;
	font-weight: bold;
	font-size: larger;
	padding-top: 6px;
}
.progressBar-title{
	color:#008996;
}
.progressBar-done{
	color:black;
	font-weight: bold;
}
.progressBar-total{
	color:black;
	font-weight: bold;
}
